pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 firstVal, uint256 secondVal) internal {
        vm.assume(firstVal != secondVal);
        try c.SetMinSum(firstVal) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(secondVal) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.MinSum() == before);
    }

    function testFuzz_run(uint256 firstVal, uint256 secondVal) public {
        _run(firstVal, secondVal);
    }

    receive() external payable {}
}
